def solve(inputs: dict) -> float:
    q=int(inputs['MOD']); n=int(inputs['K'])
    a=((int(inputs['A']),int(inputs['B'])),(int(inputs['C']),int(inputs['D'])))
    r=((1,0),(0,1))
    def mul(x,y):
        return tuple(tuple(sum(x[i][k]*y[k][j] for k in range(2))%q for j in range(2)) for i in range(2))
    while n:
        if n&1:r=mul(r,a)
        a=mul(a,a);n//=2
    return float(sum(map(sum,r)))

